const _r = $input.first().json;
const p = (_r && _r.data) ? _r.data : _r;
const state = Array.isArray(p) ? p[0] : p;
const ops = state.opportunities || [];

// Phase 0 section 3.5 constraints, enforced in workflow logic rather than prompt text.
// A score can never override a block.
const BLOCKING_ENGINES = ['real_events'];
const REVIEW_ENGINES = ['sexual_offending', 'complicity', 'murder', 'terrorism', 'institutional_failure'];
const BLOCKING_WORLDS = ['criminal_justice', 'royal_household'];

let blocked = 0, review = 0, clear = 0;
const screened = ops.map(o => {
  const reasons = [];
  if (o.legal_flag_count > 0) reasons.push('world_carries_real_case_evidence');
  if (BLOCKING_ENGINES.includes(o.engine)) reasons.push('engine_is_direct_real_events');
  if (BLOCKING_WORLDS.includes(o.world)) reasons.push('world_derived_from_identifiable_real_proceedings');

  const legal_block = reasons.length > 0;
  const needs_review = !legal_block && REVIEW_ENGINES.includes(o.engine);

  if (legal_block) blocked++; else if (needs_review) review++; else clear++;

  // Governance bands from Phase 0 section 4.1
  let band;
  if (legal_block) band = 'blocked';
  else if (o.score_total >= 75) band = 'eligible_for_development';
  else if (o.score_total >= 60) band = 'chairman_review';
  else band = 'archive';

  return Object.assign({}, o, {
    legal_block,
    legal_block_reasons: reasons,
    legal_review_required: needs_review || legal_block,
    governance_band: band,
    status: legal_block ? 'blocked' : 'screened'
  });
});

return [{ json: {
  stage: 'WF-14',
  generated_at: new Date().toISOString(),
  source_stage: state.stage,
  scoring_model_version: state.scoring_model_version,
  input_count: ops.length,
  blocked_count: blocked,
  review_required_count: review,
  clear_count: clear,
  band_counts: screened.reduce((a, o) => { a[o.governance_band] = (a[o.governance_band] || 0) + 1; return a; }, {}),
  opportunities: screened
} }];
